# muselink-common.ps1 - shared helpers for the PC-side scripts. Dot-source it:
#   . (Join-Path $PSScriptRoot 'muselink-common.ps1')
# Keep this file ASCII-only: Windows PowerShell 5.1 reads BOM-less files with
# the ANSI code page, so any literal non-ASCII text would be mangled.
#
# Every PC-side script lives in ONE tool directory (the directory of this
# file). Paths are derived from it; nothing is hard-coded to a user profile.
# Site-specific values come from muselink.json in the same directory
# (generated by install\deploy-pc.ps1 from the site file; template
# config/muselink.site.example.json, section "pc").

$script:MLDir = $PSScriptRoot
$script:MLUtf8NoBom = New-Object System.Text.UTF8Encoding($false)
$script:MLConfigCache = $null

function Get-MLDir { return $script:MLDir }

function Get-MLPath([string]$name) { return (Join-Path $script:MLDir $name) }

function Get-MLConfig {
    if ($null -ne $script:MLConfigCache) { return $script:MLConfigCache }
    $p = Get-MLPath 'muselink.json'
    $cfg = New-Object psobject
    if (Test-Path -LiteralPath $p) {
        try {
            $cfg = ([System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)) | ConvertFrom-Json
        } catch {
            [Console]::Error.WriteLine("muselink.json unreadable: " + $_.Exception.Message)
        }
    }
    $script:MLConfigCache = $cfg
    return $cfg
}

# Get-MLSetting 'popup' 'key_guard_ms' 800
function Get-MLSetting([string]$section, [string]$name, $default) {
    $cfg = Get-MLConfig
    $sec = $null
    if ($cfg.PSObject.Properties.Name -contains $section) { $sec = $cfg.$section }
    if ($null -eq $sec) { return $default }
    if ($sec.PSObject.Properties.Name -contains $name) {
        $v = $sec.$name
        if ($null -ne $v -and "$v" -ne '') { return $v }
    }
    return $default
}

# One resolver for the host and the ownership repair tool. Registry fallback
# also works when Task Scheduler has not inherited a newly set user variable.
function Get-MLAgentDesktopHome([string]$StateDir = '') {
    if ($StateDir -ne '') { return $StateDir }
    $configured = Get-MLSetting 'executor' 'agent_desktop_home' ''
    if ($configured -ne '') { return $configured }
    foreach ($scope in 'Process', 'User', 'Machine') {
        $value = [Environment]::GetEnvironmentVariable('AGENT_DESKTOP_HOME', $scope)
        if (-not [string]::IsNullOrWhiteSpace($value)) { return $value }
    }
    return (Join-Path $env:USERPROFILE '.agent-desktop')
}

function Read-MLUtf8([string]$path) {
    for ($i = 0; $i -lt 25; $i++) {
        try {
            if (-not (Test-Path -LiteralPath $path)) { return '' }
            return [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
        } catch {
            Start-Sleep -Milliseconds 100
        }
    }
    return ''
}

function Write-MLUtf8([string]$path, [string]$text) {
    [System.IO.File]::WriteAllText($path, $text, $script:MLUtf8NoBom)
}

# Write to a temp name, then rename over the target: readers never see a
# half-written file.
function Write-MLAtomic([string]$path, [string]$text) {
    $tmp = $path + '.' + $PID + '.tmp'
    [System.IO.File]::WriteAllText($tmp, $text, $script:MLUtf8NoBom)
    Move-Item -LiteralPath $tmp -Destination $path -Force
}

# popup-done.txt format (v2): line 1 = ISO timestamp, then "REQ:<id>".
# Legacy files carry only the timestamp; ReqId is then ''.
function Get-MLDoneInfo([string]$doneFile) {
    $raw = Read-MLUtf8 $doneFile
    $at = ''
    $req = ''
    foreach ($line in ($raw -split "`r?`n")) {
        $t = $line.Trim()
        if ($t -eq '') { continue }
        if ($t.StartsWith('REQ:')) { $req = $t.Substring(4).Trim() }
        elseif ($at -eq '') { $at = $t }
    }
    return @{ At = $at; ReqId = $req }
}

# Live popup windows. Excludes this process and the scripts whose own names
# contain the scanned substring (check-popup / wait-popup / popup-stage):
# the 2026-11-03 self-match incident made a dead popup look alive for four
# rounds. Any new scanner must keep this exclusion and be negative-tested.
# Only cards of THIS install count: the command line must name popup.ps1 in
# this tool dir (another install or a test copy is not ours to judge or kill).
function Get-MLPopupProcess {
    $mine = Join-Path $script:MLDir 'popup.ps1'
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue |
        Where-Object {
            $_.ProcessId -ne $PID -and $_.CommandLine -and
            $_.CommandLine.IndexOf($mine, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and
            $_.CommandLine -notmatch 'check-popup|wait-popup|popup-stage'
        }
}

function Test-MLReqId([string]$id) {
    return ($id -match '^[A-Za-z0-9][A-Za-z0-9_-]{2,95}$')
}
